actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
result.tn_franchise_tax = 0.0;
result.tn_excise_tax = 0.0;
result.tn_total_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate TN state additions
            double additions = 0.0;

            // Add back federal bond interest (not taxable federally, taxable to TN)
            if (revenue.federal_bond_interest != null) {
              additions += revenue.federal_bond_interest;
            }

            // Add back IRC 199A qualified business income deduction
            // TN does not conform to IRC § 199A
            if (result.section_199a_deduction != null) {
              additions += result.section_199a_deduction;
            }

            // Add back state franchise and excise taxes paid
            // (not deductible for TN purposes)
            if (result.state_income_taxes_paid != null) {
              additions += result.state_income_taxes_paid;
            }

            apportionment.state_additions = additions;

            // Calculate TN state subtractions
            double subtractions = 0.0;

            // Subtract TN municipal bond interest (exempt from TN tax)
            if (revenue.tn_municipal_interest != null) {
              subtractions += revenue.tn_municipal_interest;
            }

            // Subtract qualified dividends from 80%+ owned subsidiaries
            if (revenue.qualified_subsidiary_dividends != null) {
              subtractions += revenue.qualified_subsidiary_dividends;
            }

            // Subtract TN NOL carryforward (if applicable)
            if (result.tn_nol_deduction != null) {
              subtractions += result.tn_nol_deduction;
            }

            apportionment.state_subtractions = subtractions;

            // Calculate franchise tax: 0.25% on net worth
            result.tn_franchise_tax =
              result.tn_net_worth * result.tn_franchise_tax_rate;

            // Minimum tax is $100 but applies to COMBINED franchise + excise
            // (handled in table 51980)

            // Calculate excise tax: 6.5% on apportioned income
            result.tn_excise_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract TN credits from excise tax only
            result.tn_excise_tax =
              Math.max(0.0, result.tn_excise_tax - apportionment.state_credits);

            // Calculate total TN tax (franchise + excise)
            result.tn_total_tax =
              result.tn_franchise_tax + result.tn_excise_tax;

            // Apply minimum tax of $100 (combined)
            result.tn_total_tax =
              Math.max(result.tn_minimum_tax, result.tn_total_tax);

            // Set state_tax to total TN tax for standard reporting
            apportionment.state_tax = result.tn_total_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // No net earnings - excise tax is zero
            result.tn_excise_tax = 0.0;

            // Total tax is just franchise tax
            result.tn_total_tax = result.tn_franchise_tax;

            // Apply minimum tax of $100 if any franchise tax
            if (result.tn_franchise_tax > 0) {
              result.tn_total_tax =
                Math.max(result.tn_minimum_tax, result.tn_total_tax);
            }

            apportionment.state_tax = result.tn_total_tax;
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
